Here's a complete example:

**XAML**
```xml
<ContentPage xmlns="http://schemas.microsoft.com/dotnet/2021/maui"
             xmlns:x="http://schemas.microsoft.com/winfx/2009/xaml"
             x:Class="MyApp.Views.ItemsPage">

    <RefreshView IsRefreshing="{Binding IsRefreshing}"
                 Command="{Binding RefreshCommand}">

        <CollectionView ItemsSource="{Binding Items}"
                        SelectionMode="Single"
                        SelectedItem="{Binding SelectedItem}"
                        SelectionChangedCommand="{Binding ItemSelectedCommand}">
            <CollectionView.ItemTemplate>
                <DataTemplate>
                    <Grid Padding="10">
                        <Label Text="{Binding Name}" FontSize="18" />
                    </Grid>
                </DataTemplate>
            </CollectionView.ItemTemplate>
        </CollectionView>

    </RefreshView>
</ContentPage>
```

**ViewModel**
```csharp
public partial class ItemsViewModel : ObservableObject
{
    private readonly IApiService _api;
    private readonly INavigationService _nav;

    [ObservableProperty]
    private ObservableCollection<Item> _items = new();

    [ObservableProperty]
    private bool _isRefreshing;

    [ObservableProperty]
    private Item? _selectedItem;

    public ItemsViewModel(IApiService api, INavigationService nav)
    {
        _api = api;
        _nav = nav;
    }

    [RelayCommand]
    private async Task Refresh()
    {
        var data = await _api.GetItemsAsync();
        Items = new ObservableCollection<Item>(data);
        IsRefreshing = false;          // stops the spinner
    }

    [RelayCommand]
    private async Task ItemSelected()
    {
        if (SelectedItem is null) return;

        await _nav.GoToAsync(nameof(DetailPage),
            new Dictionary<string, object> { ["Item"] = SelectedItem });

        SelectedItem = null;           // reset so the same row can be re-tapped
    }
}
```

**Key bindings explained:**

| Binding | Purpose |
|---|---|
| `IsRefreshing` → `RefreshView.IsRefreshing` | Two-way: MAUI sets it `true` on pull; you set it `false` when done |
| `RefreshCommand` → `RefreshView.Command` | Fires your `Refresh()` method |
| `SelectedItem` → `CollectionView.SelectedItem` | Two-way: holds the tapped item; reset to `null` after navigation |
| `SelectionChangedCommand` | Fires `ItemSelected()` on tap; triggers navigation |

**Two things to remember:**
1. Set `SelectedItem = null` after navigating — otherwise tapping the same row again won't fire the command.
2. Set `IsRefreshing = false` when your API call finishes — otherwise the spinner stays visible indefinitely.
